const q=id=>document.getElementById(id);const DEMO_MODE=new URLSearchParams(location.search).get("live")!=="1";let use="brainstorming",courses=JSON.parse(localStorage.getItem("aipc_courses")||'["ENGL 102"]'),activeCourse=localStorage.getItem("aipc_active")||courses[0],saveTimer;const fields=["course","prof","profEmail","policy","tool"],isFa=()=>q("language")?.value==="fa";
const courseKey=()=>"aipc_data_"+activeCourse.toLowerCase().replace(/[^a-z0-9]+/gi,"_");
function setStep(n){document.querySelectorAll("#steps span").forEach((el,i)=>el.classList.toggle("active",i<n))}
function saveCourse(){const data={};fields.forEach(id=>data[id]=q(id)?.value||"");data.use=use;localStorage.setItem(courseKey(),JSON.stringify(data));q("saveStatus").textContent=isFa()?"ذخیره شد ✓":"Saved ✓"}
function saveSoon(){clearTimeout(saveTimer);q("saveStatus").textContent=isFa()?"در حال ذخیره…":"Saving…";saveTimer=setTimeout(saveCourse,350)}
function selectUse(v){use=v;document.querySelectorAll("#uses button").forEach(b=>b.classList.toggle("on",b.dataset.u===v));saveSoon()}
function loadCourse(){const d=JSON.parse(localStorage.getItem(courseKey())||"{}");fields.forEach(id=>q(id).value=id==="course"?activeCourse:(d[id]||""));selectUse(d.use||"brainstorming");["flow","resultCard","nextSteps","promptCard","ask"].forEach(id=>q(id).classList.add("hidden"));setStep(1)}
function renderCourses(){const box=q("courseTabs");box.innerHTML="";courses.forEach(name=>{const b=document.createElement("button");b.className="course-tab"+(name===activeCourse?" active":"");b.textContent=name;b.onclick=()=>{saveCourse();activeCourse=name;localStorage.setItem("aipc_active",name);renderCourses();loadCourse()};box.appendChild(b)});q("course").value=activeCourse}
q("addCourse").onclick=()=>{const name=prompt("Course name (example: BIO 101)")?.trim();if(!name)return;if(!courses.includes(name))courses.push(name);saveCourse();activeCourse=name;localStorage.setItem("aipc_courses",JSON.stringify(courses));localStorage.setItem("aipc_active",name);renderCourses();loadCourse()};fields.forEach(id=>q(id).addEventListener("input",saveSoon));
q("start").onclick=()=>{const hasFile=q("syllabusFile").files[0]||q("assignmentFile").files[0],hasText=q("policy").value.trim();if(!hasFile&&!hasText){q("formMessage").textContent=isFa()?"ابتدا برنامه درسی یا تکلیف را اضافه کن، یا بخش مربوط به قوانین را اینجا بچسبان.":"Add a syllabus, assignment, or paste the relevant instructions first.";q("formMessage").classList.remove("hidden");q("policy").focus();return}q("formMessage").classList.add("hidden");q("flow").classList.remove("hidden");q("courseStatus").textContent=hasText?(isFa()?"متن قوانین آماده است ✓":"Policy text loaded ✓"):(isFa()?"فایل اضافه شد — برای نتیجه دقیق‌تر بخش هوش مصنوعی را بچسبان":"File added — paste the AI section for the most accurate result");setStep(3);saveCourse();q("flow").scrollIntoView({behavior:"smooth"})};
document.querySelectorAll("#uses button").forEach(b=>b.onclick=()=>selectUse(b.dataset.u));
const restrictive=[/no\s+(generative\s+)?ai/i,/ai\s+(is|tools?\s+are)\s+(prohibited|forbidden|not permitted|not allowed)/i,/may not use\s+(generative\s+)?ai/i,/without (the )?use of ai/i],permissive=[/ai\s+(is|tools?\s+are)\s+(allowed|permitted)/i,/may use\s+(generative\s+)?ai/i,/can use\s+(generative\s+)?ai/i,/use of ai is permitted/i],limited=[/brainstorm/i,/grammar/i,/feedback/i,/outline/i,/cite|citation|disclos/i,/with (prior )?(approval|permission)/i];
function findEvidence(text,patterns){return text.split(/(?<=[.!?])\s+|\n+/).filter(Boolean).find(s=>patterns.some(p=>p.test(s)))||""}
q("decide").onclick=()=>{const raw=q("policy").value.trim(),t=raw.toLowerCase(),ban=findEvidence(t,restrictive),allow=findEvidence(t,permissive),limit=findEvidence(t,limited),learningPatterns=[/ai is a powerful learning tool and may be used to help you understand course content/i,/acceptable use:\s*asking ai to explain a concept/i,/asking ai to explain a concept/i],submissionPatterns=[/unacceptable use:\s*copying and pasting text into an assignment/i,/ai generated content such as chatgpt[^.]*plagiarism/i,/pretending that you wrote it/i],learningEvidence=findEvidence(raw,learningPatterns),submissionEvidence=findEvidence(raw,submissionPatterns),isLearningUse=use==="explaining concepts",isAnswerUse=use.includes("graded")||use.includes("quiz");let s="yellow",title="🟡 CHECK FIRST",msg="The provided information does not clearly authorize this specific AI use.",ev="No explicit policy language was provided.";if(isAnswerUse&&submissionEvidence){s="red";title="🔴 NOT ALLOWED";msg="The syllabus allows AI for learning, but not for submitting AI-generated answers as your own work.";ev='Relevant policy language: “'+submissionEvidence.slice(0,300)+'”'}else if(isLearningUse&&learningEvidence){s="green";title="🟢 APPEARS ALLOWED";msg="The syllabus specifically allows AI to help explain and understand course concepts.";ev='Relevant policy language: “'+learningEvidence.slice(0,300)+'”'}else if(ban){s="red";title="🔴 NOT ALLOWED";msg="The policy appears to restrict AI for this work.";ev='Relevant policy language: “'+findEvidence(raw,restrictive).slice(0,300)+'”'}else if(allow){s="green";title="🟢 APPEARS ALLOWED";msg="The policy appears to allow AI, subject to any stated limits.";ev='Relevant policy language: “'+findEvidence(raw,permissive).slice(0,300)+'”'}else if(limit)ev='A limit or condition was found: “'+findEvidence(raw,limited).slice(0,300)+'”';if(isAnswerUse&&s==="green"){s="yellow";title="🟡 CHECK FIRST";msg="General permission may not cover AI-generated graded answers. Confirm this exact use."}q("result").className="result "+s;q("title").textContent=title;q("text").textContent=msg;q("evidence").textContent=ev;const steps=s==="green"?["Follow any citation or disclosure requirement in the policy.","Keep your prompts and drafts in case your professor asks.","Make sure the final work reflects your own understanding."]:s==="red"?["Do not use AI for the selected purpose.","Complete the work using the resources your professor allows.","Ask your professor if you need an approved alternative or accommodation."]:["Pause before using AI for this purpose.","Send the prepared question below to your professor.","Keep the professor’s reply with your assignment records."];q("checklist").innerHTML=steps.map(x=>`<li>${x}</li>`).join("");q("resultCard").classList.remove("hidden");q("nextSteps").classList.remove("hidden");q("ask").classList.toggle("hidden",s!=="yellow");if(s==="yellow")email();setStep(s==="yellow"?5:4);q("resultCard").scrollIntoView({behavior:"smooth"})};
function email(){const c=q("course").value||"[Course Name]",p=q("prof").value||"Professor",tool=q("tool").value,subject=`Clarification on AI Use for ${c}`,body=`Hello ${p},\n\nI want to make sure I follow the AI policy for ${c}. The policy or assignment instructions are unclear to me about using ${tool} for ${use}.\n\nWould this specific use be permitted for this work? If so, are there limits or citation/disclosure requirements I should follow?\n\nI want my work to follow the course policy and reflect my own learning.\n\nThank you.`;q("email").textContent=`Subject: ${subject}\n\n${body}`;q("openEmail").href=`mailto:${encodeURIComponent(q("profEmail").value)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
q("copy").onclick=async()=>{try{await navigator.clipboard.writeText(q("email").textContent);q("copyStatus").textContent=isFa()?"کپی شد ✓":"Copied ✓"}catch{q("copyStatus").textContent=isFa()?"متن بالا را انتخاب و دستی کپی کن.":"Select the text above and copy it manually."}};q("checkAnother").onclick=()=>{["resultCard","nextSteps","promptCard","ask"].forEach(id=>q(id).classList.add("hidden"));setStep(3);q("uses").scrollIntoView({behavior:"smooth"})};q("samplePolicy").onclick=()=>{q("policy").value="Students may use AI tools for brainstorming and grammar feedback. AI-generated writing may not be submitted as the student's own work. Any AI use must be disclosed and cited.";saveSoon();q("formMessage").textContent=isFa()?"نمونه با موفقیت بارگذاری شد ✓":"Example loaded successfully ✓";q("formMessage").classList.remove("hidden");q("formMessage").classList.add("success");setTimeout(()=>q("start").click(),300)};q("clearPolicy").onclick=()=>{q("policy").value="";q("formMessage").classList.add("hidden");q("formMessage").classList.remove("success");saveSoon();q("policy").focus()};
