 en:{hero:["Welcome to your","AI Assistant Policy Campus","Upload once. Understand the rule. Know your next step."],steps:["1 Upload","2 Sources","3 AI Use","4 Decision","5 Ask Professor"],course:["My Courses","Keep each class and its policy in one place."],buttons:["＋ Add Class","Check My AI Use →","Try an example","Clear","Show My Decision →","Check another AI use","Copy Professor Email","Open email app"],heads:["Upload your syllabus or assignment","Rules that may apply","What do you want AI to help with?","Your next steps","Ask My Professor"],kickers:["START HERE","POLICY SOURCES","AI TOOL + PURPOSE","YOUR RESULT","WHAT TO DO NOW","WHEN IT'S UNCLEAR"],uses:["Brainstorming","Explain concepts","Grammar / feedback","Research","Coding","Write my answer","Quiz / Test"],labels:["Course","Professor","Professor Email","Or paste the relevant policy / instructions","Preferred AI tool"],placeholders:["ENGL 102","Professor name","professor@college.edu","Paste policy or assignment instructions..."],access:["♿ Accessibility","Accessibility","A+ Larger text","◐ High contrast","◌ Reduce motion","🔊 Read page"],upload:["📘 Upload Syllabus","PDF, Word, or TXT","? Where can I find my syllabus?","📝 Upload Assignment","Optional — add it when checking a specific task"],sources:["📘 Course Policy","Student-provided syllabus","🏫 College Policy","Academic integrity / plagiarism","🏛 State / System Guidance","Official AI guidance, when applicable"],misc:["We’ll use the information you provide to help identify the AI rules for this specific work.","Choose the closest match. Your result applies only to this use.","This result is about the specific AI use you selected — not AI in general.","We use the course, AI tool, selected use, and unclear policy to prepare the question.","Keyboard-friendly controls, visible focus, screen-reader labels, and color + text status are included.","Prototype: official school and state links will be connected here.","AI Policy First. Learning Always."]},
