fr:{hero:["Bienvenue sur votre","Guide des politiques d’IA","Ajoutez le syllabus et le devoir. Obtenez une réponse claire, un courriel et un prompt sûr."],steps:["1 Importer","2 Sources","3 Usage IA","4 Décision","5 Professeur"],course:["Mes cours","Gardez chaque cours et sa politique au même endroit."],buttons:["＋ Ajouter un cours","Vérifier mon usage →","Voir un exemple","Effacer","Afficher la décision →","Vérifier un autre usage","Copier le courriel","Ouvrir la messagerie"],heads:["Importez le syllabus ou le devoir","Règles applicables","Comment voulez-vous utiliser l’IA ?","Vos prochaines étapes","Demandez au professeur"],kickers:["COMMENCEZ ICI","SOURCES","OUTIL ET OBJECTIF","VOTRE RÉSULTAT","QUE FAIRE","SI CE N’EST PAS CLAIR"],uses:["Idées","Expliquer des notions","Grammaire et retours","Recherche","Code","Rédiger ma réponse","Quiz ou examen"],labels:["Cours","Professeur","Courriel du professeur","Ou collez la politique ou les consignes","Outil d’IA préféré"],placeholders:["ex. ENGL 102","Nom du professeur","professeur@universite.edu","Collez la politique ou les consignes..."],access:["♿ Accessibilité","Accessibilité","A+ Texte agrandi","◐ Contraste élevé","◌ Réduire les animations","🔊 Lire la page"],upload:["📘 Importer le syllabus","PDF, Word ou TXT","Où trouver mon syllabus ?","📝 Importer le devoir","Facultatif pour une tâche précise"],sources:["📘 Politique du cours","Syllabus fourni par l’étudiant","🏫 Politique universitaire","Intégrité académique et plagiat","🏛 Guide de l’État ou du système","Guide officiel sur l’IA"],misc:["Nous utilisons vos informations pour trouver les règles de ce travail.","Choisissez l’option la plus proche ; le résultat concerne cet usage.","Ce résultat concerne l’usage choisi, pas l’IA en général.","Nous préparons la question avec le cours, l’outil et l’usage.","Navigation clavier, focus visible et lecteur d’écran inclus.","Prototype : les liens officiels seront ajoutés ici.","La politique d’abord. Toujours apprendre."]},
