function setLanguage(v){const t=ui[v]||ui.en;setMany(".welcome,.hero h1,.hero>p:last-child",t.hero);setMany("#steps span",t.steps);setMany(".courses-bar>div:first-child b,.courses-bar>div:first-child small",t.course);setMany("#addCourse,#start,#samplePolicy,#clearPolicy,#decide,#checkAnother,#copy,#openEmail",t.buttons);[...document.querySelectorAll(".card .body>h2")].filter(el=>!el.closest("#promptCard")).forEach((el,i)=>{if(t.heads[i])el.textContent=t.heads[i]});[...document.querySelectorAll(".card .body>small")].filter(el=>!el.closest("#promptCard")).forEach((el,i)=>{if(t.kickers[i])el.textContent=t.kickers[i]});setMany("#uses button",t.uses);setMany(".sources b,.sources em",t.sources);const miscNodes=[document.querySelector("main>section.card .body>p"),document.querySelector(".selection-hint"),document.querySelector("#resultCard .note"),document.querySelector("#ask .body>p"),document.querySelector("#accessPanel>p"),document.querySelector("#flow>section.card:first-child .note"),document.querySelector("footer")];miscNodes.forEach((el,i)=>{if(el)el.textContent=t.misc[i]});["course","prof","profEmail","policy","tool"].forEach((id,i)=>setLabel(id,t.labels[i]));["course","prof","profEmail","policy"].forEach((id,i)=>q(id).placeholder=t.placeholders[i]);setMany("#accessBtn,#accessPanel>b,#textPlus,#contrast,#motion,#readPage",t.access);const uploads=document.querySelectorAll(".upload");uploads[0].querySelector("b").textContent=t.upload[0].replace("📘 ","");uploads[0].querySelector(".upload-format").textContent=t.upload[1];q("syllabusHelpBtn").textContent=t.upload[2];uploads[1].querySelector("b").textContent=t.upload[3].replace("📝 ","");uploads[1].querySelector(".upload-format").textContent=t.upload[4];document.documentElement.dir=["fa","ar","ur"].includes(v)?"rtl":"ltr";document.documentElement.lang=v;localStorage.setItem("aipc_language",v);q("saveStatus").textContent=v==="fa"?"روی این دستگاه ذخیره می‌شود":"Saved on this device";translateResources(v);translateFloating(v);translateAid(v)}
function translateExtras(v){const fa=v==="fa";document.querySelector(".lang-label span").textContent=fa?"زبان":"Language";if(!["en","fa"].includes(v))return;document.querySelector(".policy-first").textContent=fa?"اول قوانین هوش مصنوعی":"AI Policy First.";q("courseStatus").textContent=fa?"برنامه درسی بارگذاری‌شده توسط دانش‌آموز":"Student-provided syllabus";const help=q("syllabusHelp");help.querySelector("b").textContent=fa?"معمولاً در صفحه درس دانشگاه پیدا می‌شود:":"Usually in your college course page:";const ps=help.querySelectorAll("p");ps[0].textContent=fa?"صفحه درس را باز کن ← بخش‌های «برنامه درسی»، «اطلاعات درس»، «ماژول‌ها» یا «فایل‌ها» را پیدا کن ← فایل PDF یا Word را دانلود و اینجا بارگذاری کن.":"Open your class → look for Syllabus, Course Information, Modules, or Files → download the PDF/Word file → upload it here.";ps[1].textContent=fa?"اگر باز هم پیدایش نکردی، از استاد بپرس آخرین نسخه برنامه درسی کجا قرار دارد.":"If you still can’t find it, ask your professor where the current syllabus is posted."}
