function xmlEscape(value){return String(value).replace(/[<>&'\"]/g,c=>({"<":"&lt;",">":"&gt;","&":"&amp;","'":"&apos;",'"':"&quot;"}[c]))}
function createDemoVisual(){const a=window.lessonAnalysis,rtl=isFa(),points=(a?.key_points||[]).slice(0,4);const rows=points.map((p,i)=>`<text x="${rtl?1120:80}" y="${390+i*92}" text-anchor="${rtl?"end":"start"}" font-size="30" fill="#173363">${xmlEscape(i+1+". "+p).slice(0,105)}</text>`).join("");const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><rect width="1200" height="800" rx="36" fill="#f5f9ff"/><rect x="42" y="42" width="1116" height="716" rx="28" fill="#fff" stroke="#2c5d91" stroke-width="4"/><rect x="70" y="70" width="210" height="48" rx="24" fill="#936b14"/><text x="175" y="103" text-anchor="middle" font-family="Arial" font-weight="700" font-size="23" fill="#fff">DEMO PREVIEW</text><text x="${rtl?1120:80}" y="190" text-anchor="${rtl?"end":"start"}" direction="${rtl?"rtl":"ltr"}" font-family="Arial" font-weight="700" font-size="52" fill="#102b59">${xmlEscape(a?.title||"Study guide")}</text><text x="${rtl?1120:80}" y="265" text-anchor="${rtl?"end":"start"}" direction="${rtl?"rtl":"ltr"}" font-family="Arial" font-size="25" fill="#52627a">${xmlEscape(a?.summary||"").slice(0,105)}</text><g font-family="Arial" direction="${rtl?"rtl":"ltr"}">${rows}</g><text x="600" y="720" text-anchor="middle" font-family="Arial" font-size="22" fill="#6b778c">AI Policy Campus · Accessible learning preview</text></svg>`;return URL.createObjectURL(new Blob([svg],{type:"image/svg+xml"}))}
