async function createAccessibleAid(){const file=q("assignmentFile").files[0]||q("syllabusFile").files[0];let text=q("policy").value.trim();const fa=isFa();if(!file&&!text){q("formMessage").textContent=fa?"ابتدا فایل درس یا اسایمنت را بارگذاری کن، یا متن را در کادر بچسبان.":"Upload a lesson or assignment, or paste its text first.";q("formMessage").classList.remove("hidden");return}q("accessibleAid").classList.remove("hidden");q("accessibleAid").scrollIntoView({behavior:"smooth",block:"start"});if(DEMO_MODE){createDemoAid(file);return}q("accessibleAid").classList.add("loading");q("aidStatus").textContent=fa?"در حال خواندن و تحلیل فایل…":"Reading and analyzing the file…";try{if(location.protocol==="file:")throw new Error("server-required");if(file&&file.name.toLowerCase().endsWith(".txt")&&!text)text=await file.text();const payload={name:file?.name||"lesson.txt",mime:file?.type||"text/plain",lang:q("language").value,text};if(file&&!file.name.toLowerCase().endsWith(".txt"))payload.base64=await fileBase64(file);const response=await fetch("/api/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!response.ok)throw new Error("analysis-unavailable");const data=await response.json();window.lessonAnalysis=data;q("lessonTitle").textContent=data.title;q("lessonSummary").textContent=data.summary;renderLessonPoints([...(data.objectives||[]),...(data.key_points||[]),...(data.study_steps||[])].slice(0,9));q("aidPrompt").value=data.safe_prompt;q("aidStatus").textContent=fa?"تحلیل آماده شد؛ حالا خروجی صوتی یا تصویری را انتخاب کن ✓":"Analysis is ready. Choose audio or a visual study card ✓"}catch(error){if(createLocalAid())q("aidStatus").textContent=fa?"نسخه ساده آماده شد؛ برای تحلیل کامل، اعتبار API را بررسی کن.":"A basic guide is ready. Check API credit for full analysis.";else q("aidStatus").textContent=fa?"فایل انتخاب شد، اما تحلیل انجام نشد؛ اعتبار API را بررسی کن.":"The file is selected, but analysis failed. Check API credit."}finally{q("accessibleAid").classList.remove("loading")}}
